import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

// Get the directory name of the current module
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Get the project root directory (two levels up from __dirname)
const projectRoot = join(__dirname, "../../");

export type GStreamerPropertyPrimitiveValue = string | number | boolean | bigint;
export type GStreamerPropertyValue =
  | GStreamerPropertyPrimitiveValue
  | GStreamerPropertyPrimitiveValue[];

// Sample object returned for GST_VALUE_HOLDS_SAMPLE properties
export type GStreamerSample = {
  buffer?: Buffer;

  // Timing and offset information from the sample's buffer (omitted when the buffer has no
  // valid value for that field)
  pts?: number; // Presentation timestamp (nanoseconds)
  dts?: number; // Decode timestamp (nanoseconds)
  duration?: number; // Buffer duration (nanoseconds)
  offset?: number; // Media-specific start offset
  offsetEnd?: number; // Media-specific end offset

  flags?: number;
  caps?: {
    name?: string;
    // Additional structure fields (format, width, height, framerate, etc.)
    [key: string]: GStreamerPropertyValue | undefined;
  };
};

// GStreamer message object returned by busPop
export type GstMessage = {
  type: string;
  srcElementName?: string;
  timestamp: bigint;
  structureName?: string;
  // Structure fields are added dynamically based on message content
  [key: string]: GStreamerPropertyValue | undefined;

  // Error message specific fields
  errorMessage?: string;
  errorDomain?: string;
  errorCode?: number;
  debugInfo?: string;

  // Warning message specific fields
  warningMessage?: string;
  warningDomain?: string;
  warningCode?: number;

  // State change message specific fields
  oldState?: number;
  newState?: number;
  pendingState?: number;
};

// Extended return types including arrays, buffers, and samples
export type GStreamerPropertyReturnValue =
  | GStreamerPropertyValue
  | Record<string, GStreamerPropertyValue>
  | Buffer
  | GStreamerSample
  | null;

export type GStreamerPropertyResult =
  | { type: "primitive"; value: GStreamerPropertyPrimitiveValue }
  | { type: "array"; value: GStreamerPropertyPrimitiveValue[] }
  | { type: "object"; value: Record<string, GStreamerPropertyValue> }
  | { type: "buffer"; value: Buffer }
  | { type: "sample"; value: GStreamerSample }
  | null;

// State change result returned by play(), pause(), and stop()
export type StateChangeResult = {
  result: "success" | "async" | "no-preroll" | "failure" | "unknown";
  finalState: number;
  targetState: number;
};

export type RTPData = {
  timestamp: number;
  sequence: number;
  ssrc: number;
  payloadType: number;
};

export type GstPad = {
  name: string;
  direction: number; // 0 = unknown, 1 = src, 2 = sink
  caps: string | null;
};

export type BufferData = {
  // Raw buffer data
  buffer?: Buffer;

  // Timing information
  pts?: number; // Presentation timestamp (nanoseconds)
  dts?: number; // Decode timestamp (nanoseconds)
  duration?: number; // Buffer duration (nanoseconds)
  offset?: number;
  offsetEnd?: number;

  // Buffer flags
  flags: number;

  // Caps information (stream format)
  caps?: {
    name?: string;
    [key: string]: GStreamerPropertyValue | undefined;
  };

  // RTP-specific data (only present for RTP streams)
  rtp?: RTPData;
};

// First-frame timecode seeding types.
export type TimecodeValue = {
  hours: number;
  minutes: number;
  seconds: number;
  frames: number;
  dropFrame?: boolean;
};

export type Rational = { numerator: number; denominator: number };

export type SetFirstFrameOptions = {
  // The label to stamp on the first recorded frame (already computed by the caller).
  timecode: TimecodeValue;
  // Output/negotiated frame rate. If omitted, read from negotiated caps.
  rate?: Rational;
  // Monotonic instant of the reference snapshot, same domain as the pipeline
  // clock. Reserved for a caller-side clock bridge; unused by the seed itself.
  monotonicNs?: bigint;
  // Element whose base_time the clock bridge should report. Pass the
  // element of the pipeline the first buffer's running-time is relative to, so
  // `runningTimeNs + baseTimeNs` stays in one domain. Under interpipe
  // passthrough-ts that is the INGEST pipeline's element; omit it and the probe
  // uses this (the stamper's) base time — correct for compensate-ts. Both
  // pipelines must share one GstClock for the mapping to be valid.
  baseTimeElement?: ElementBase;
};

// A clock-bridge sample, captured together inside the probe at the first buffer.
// Lets the caller map the frame's capture instant onto an external reference
// clock. All nanoseconds; a field is absent when it was unavailable.
//   captureGstClockNs = runningTimeNs + baseTimeNs
//   (gstClockNs, monotonicNs) is an epoch bridge sampled at the same instant —
//   monotonicNs is CLOCK_MONOTONIC (same source as Node process.hrtime.bigint on
//   Linux), so the caller can translate a GstClock instant into its own domain.
//   baseClockMatched is whether baseTimeElement shares the stamper's GstClock, so
//   baseTimeNs is comparable to that epoch bridge; true when no baseTimeElement
//   was supplied, false ⇒ different clock domain, do not map.
export type FirstFrameClockBridge = {
  runningTimeNs?: number;
  baseTimeNs?: number;
  gstClockNs?: number;
  monotonicNs?: number;
  baseClockMatched?: boolean;
};

// The applied label, read back from the stamper on the first buffer. Reflects the
// value actually stamped, at the negotiated rate.
export type FirstFrameTimecodeResult = {
  timecode: string; // "HH:MM:SS:FF" / "HH:MM:SS;FF"
  pts?: number; // first-frame PTS (ns)
  framerate: Rational;
  dropFrame: boolean;
  clockBridge: FirstFrameClockBridge;
};

export type ElementBase = {
  getElementProperty: (key: string) => GStreamerPropertyResult;
  setElementProperty: (key: string, value: GStreamerPropertyValue) => void;
  addPadProbe: (padName: string, callback: (bufferData: BufferData) => void) => () => void;
  // Arms the seed synchronously (before play) and resolves once the first buffer
  // is stamped, with the label the stamper actually applied. Resolves null if the
  // stream ends (EOS) or flushes before any buffer arrives — e.g. an aborted
  // start. Call this before play() and await the returned Promise later.
  setFirstFrameTimecode: (options: SetFirstFrameOptions) => Promise<FirstFrameTimecodeResult | null>;
  setPad: (attribute: string, padName: string) => void;
  getPad: (padName: string) => GstPad | null;
};

type Element = {
  readonly type: "element";
} & ElementBase;

export type AppSinkElement = {
  readonly type: "app-sink-element";
  getSample(timeoutMs?: number): Promise<GStreamerSample | null>;
  onSample(callback: (sample: GStreamerSample) => void): () => void;
} & ElementBase;

export type AppSrcElement = {
  readonly type: "app-src-element";
  push(buffer: Buffer, pts?: Buffer | number): void;
  endOfStream(): void;
} & ElementBase;

interface Pipeline {
  play(timeoutMs?: number): Promise<StateChangeResult>;
  pause(timeoutMs?: number): Promise<StateChangeResult>;
  stop(timeoutMs?: number): Promise<StateChangeResult>;
  playing(): boolean;
  getElementByName(name: string): Element | AppSinkElement | AppSrcElement | null;
  queryPosition(): number;
  queryDuration(): number;
  busPop(timeoutMs?: number): Promise<GstMessage | null>;
  seek(positionSeconds: number): boolean;
  endOfStream(): boolean;
  dispose(): void;
}

interface PipelineConstructor {
  new (pipeline: string): Pipeline;
  elementExists(elementName: string): boolean;
}

// Define the interface for the native addon
interface NativeAddon {
  Pipeline: PipelineConstructor;
  GStreamerPropertyValue: GStreamerPropertyValue;
  GStreamerSample: GStreamerSample;
  GStreamerPropertyReturnValue: GStreamerPropertyReturnValue;
}

// Create require function for ESM
const require = createRequire(import.meta.url);

// Load the native addon
const nativeAddon: NativeAddon = require(join(projectRoot, "build/Release/gst_kit.node"));

/**
 * https://gstreamer.freedesktop.org/documentation/gstreamer/gstbuffer.html?gi-language=c#GstBufferFlags
 * */
export const GstBufferFlags = {
  GST_BUFFER_FLAG_LIVE: 16,
  GST_BUFFER_FLAG_DECODE_ONLY: 32,
  GST_BUFFER_FLAG_DISCONT: 64,
  GST_BUFFER_FLAG_RESYNC: 128,
  GST_BUFFER_FLAG_CORRUPTED: 256,
  GST_BUFFER_FLAG_MARKER: 512,
  GST_BUFFER_FLAG_HEADER: 1024,
  GST_BUFFER_FLAG_GAP: 2048,
  GST_BUFFER_FLAG_DROPPABLE: 4096,
  GST_BUFFER_FLAG_DELTA_UNIT: 8192,
  GST_BUFFER_FLAG_TAG_MEMORY: 16384,
  GST_BUFFER_FLAG_SYNC_AFTER: 32768,
  GST_BUFFER_FLAG_NON_DROPPABLE: 65536,
  GST_BUFFER_FLAG_LAST: 1048576,
} as const;

const { Pipeline: PipelineClass } = nativeAddon;

export { PipelineClass as Pipeline };

export default { ...nativeAddon, GstBufferFlags };
